# Stable de-duplication while preserving recovered wording/order.
seen = set()
items = [(theme, text) for theme, text in items if not (text in seen or seen.add(text))]

rows = []
for theme, text in items:
    rows.append('      [' + json.dumps(theme, ensure_ascii=False) + ',' + json.dumps(text, ensure_ascii=False) + ']')
block = '    const AFFIRMATIONS = [\n' + ',\n'.join(rows) + '\n    ].map((x, i) => ({ id: `f${i+1}`, theme: x[0], text: x[1] }));'

pattern = r"    const AFFIRMATIONS = \[.*?\n    \]\.map\(\(x, i\) => \(\{ id: `[^`]+`, theme: x\[0\], text: x\[1\] \}\)\);"
src, n = re.subn(pattern, lambda m: block, src, count=1, flags=re.S)
if n != 1:
    raise SystemExit(f'Could not replace AFFIRMATIONS block: {n}')

src = src.replace('affirm_mne_vygodno_saved', 'affirm_full_diary_saved_v1')
p.write_text(src, encoding='utf-8')
print(f'Installed {len(items)} unique diary affirmations')
